// The geotech axis gets litho's review-and-accept correlation loop.
//
// Until now geotech ties could only be regenerated by "Subdivide all bodies", which
// deletes ALL geotech data for the whole model — so the only way to get the automatic
// ties back was to destroy every correlation drawn by hand. This suite pins the two
// verbs that break that trade-off: a standalone auto-correlate that PROPOSES ties, and
// an accept verb that promotes the proposals the engineer keeps.
//
// The owner's invariant is the reason this file exists: pressing auto-correlate
// mid-hand-correlation must never remove or alter an edge he drew. GC5 pins that at the
// only layer this suite can see it — the set of endpoints the click is allowed to reach.
//
// The litho axis appears throughout as the control. A geotech-only expectation proves
// nothing on its own: it would pass just as well if the verb had been removed for
// everyone.

import { cleanup, fireEvent, render, screen, waitFor } from '@testing-library/react'
import { afterEach, describe, expect, it, vi } from 'vitest'

import { ShellContext } from '../../ShellContext'
import type { ShellContextValue } from '../../ShellContext'
import type { SectionModelAxis } from '../../../hooks/useSections'
import SectionsToolbar from './SectionsToolbar'
import {
  makeShellCtx,
  makeGeotechModel,
  makeLithoModel,
} from './__fixtures__/sectionsShellContext'

// ---------------------------------------------------------------------------
// Module mocks
// ---------------------------------------------------------------------------

const autoCorrelateGeotech = vi.fn().mockResolvedValue({
  edges_proposed: 0,
  edges_skipped_existing: 0,
  sections_processed: 0,
  skipped_no_lcs: 0,
  skipped_empty_stack: 0,
})
const acceptContactCorrelations = vi
  .fn()
  .mockResolvedValue({ edges_accepted: 0, ordinals_changed: 0 })
const deleteAutoCorrelations = vi.fn().mockResolvedValue({ deleted: 0 })
const subdivideAllBodies = vi.fn().mockResolvedValue({})
const autoCorrelateContacts = vi
  .fn()
  .mockResolvedValue({ edges_created: 0, edges_skipped_existing: 0 })

vi.mock('../../../api/client', async () => {
  const actual = await vi.importActual<typeof import('../../../api/client')>('../../../api/client')
  return {
    ...actual,
    setBaseUrl: vi.fn(),
    api: {
      geology: {
        validateCrossings: vi.fn().mockResolvedValue({ model_id: '', issues: [] }),
        listContactCorrelations: vi.fn().mockResolvedValue([]),
        autoCorrelateGeotech: (...args: unknown[]) => autoCorrelateGeotech(...args),
        acceptContactCorrelations: (...args: unknown[]) => acceptContactCorrelations(...args),
        deleteAutoCorrelations: (...args: unknown[]) => deleteAutoCorrelations(...args),
        subdivideAllBodies: (...args: unknown[]) => subdivideAllBodies(...args),
        autoCorrelateContacts: (...args: unknown[]) => autoCorrelateContacts(...args),
      },
      virtueleBoring: { getModels: vi.fn().mockResolvedValue([]) },
    },
  }
})

vi.mock('../../../utils/log', () => ({
  log: {
    debug: vi.fn(),
    info: vi.fn(),
    warn: vi.fn(),
    error: vi.fn(),
    success: vi.fn(),
  },
}))

// ---------------------------------------------------------------------------
// Context — the shared sections fixture, patched per case
// ---------------------------------------------------------------------------

interface CtxOverrides {
  geoModel?: Partial<ShellContextValue['geoModel']>
  sections?: Partial<ShellContextValue['sections']>
  toast?: ShellContextValue['toasts']['toast']
}

function makeCtx(axis: SectionModelAxis, overrides: CtxOverrides = {}): ShellContextValue {
  const base = makeShellCtx(axis)
  return {
    ...base,
    geoModel: { ...base.geoModel, ...(overrides.geoModel ?? {}) },
    sections: { ...base.sections, ...(overrides.sections ?? {}) },
    toasts: { ...base.toasts, toast: overrides.toast ?? base.toasts.toast },
  }
}

function renderToolbar(ctx: ShellContextValue): void {
  render(
    <ShellContext.Provider value={ctx}>
      <SectionsToolbar />
    </ShellContext.Provider>,
  )
  openPipelineMenu()
}

/** The pipeline steps live in the "Packing pipeline" dropdown (owner
 *  2026-08-05). Open it right after render so the step items are queryable —
 *  an item click auto-closes the menu, which is fine for these single-press
 *  scenes. No-op off the geotech axis (the trigger is absent there). */
function openPipelineMenu(): void {
  const trigger = screen.queryByTestId('geotech-pipeline')
  if (trigger && !(trigger as HTMLButtonElement).disabled) {
    fireEvent.click(trigger)
  }
}


afterEach(() => {
  cleanup()
  vi.clearAllMocks()
})

// ---------------------------------------------------------------------------
// GC — the standalone geotech auto-correlate verb
// ---------------------------------------------------------------------------

describe('SectionsToolbar — geotech auto-correlate', () => {
  it('GC1 — the verb is reachable on the geotech axis', () => {
    renderToolbar(makeCtx('geotechnical'))
    expect(screen.getByTestId('geotech-auto-correlate')).toBeTruthy()
  })

  it('GC2 — the verb is absent on the litho axis (control)', () => {
    renderToolbar(makeCtx('lithostratigraphic'))
    expect(screen.queryByTestId('geotech-auto-correlate')).toBeNull()
    // The litho axis keeps its own auto-correlate — this is a second verb, not a move.
    expect(screen.getByTestId('correlate-mode-caret')).toBeTruthy()
  })

  it('GC3 — pressing it asks the GEOTECH model for proposals across the whole model', async () => {
    // RE-PINNED 2026-08-05 (review MAJOR-2): the pipeline gate is model-wide,
    // so its feeder verbs are too. The geotech model id — never the litho
    // parent — and a null section = every section.
    renderToolbar(makeCtx('geotechnical'))
    fireEvent.click(screen.getByTestId('geotech-auto-correlate'))
    await waitFor(() => expect(autoCorrelateGeotech).toHaveBeenCalled())
    expect(autoCorrelateGeotech).toHaveBeenCalledWith('proj-1', 'geotech-model-1', null)
  })

  it('GC4 — the verb is disabled until a geotech model exists', () => {
    renderToolbar(makeCtx('geotechnical', { geoModel: { activeGeotechModel: null } }))
    expect(screen.getByTestId('geotech-auto-correlate')).toBeDisabled()
  })

  it('GC4b — the verb works with no section open (model-wide, MAJOR-2 re-pin)', () => {
    // Proposals are REVIEWED per section (pending style + per-tie accept), but
    // proposing is model-wide so the model-wide gate can ever be satisfied.
    renderToolbar(makeCtx('geotechnical', { sections: { selectedSectionId: null } }))
    expect(screen.getByTestId('geotech-auto-correlate')).not.toBeDisabled()
  })

  it('GC5 — it adds; it never deletes or rebuilds (the owner invariant)', async () => {
    // Pressing this mid-hand-correlation must be safe at any moment. At this layer that
    // means exactly one endpoint is reached: the proposal endpoint. Not the auto-edge
    // delete the litho re-correlate flow uses, and above all not the subdivide that
    // wipes every geotech row in the model.
    renderToolbar(makeCtx('geotechnical'))
    fireEvent.click(screen.getByTestId('geotech-auto-correlate'))
    await waitFor(() => expect(autoCorrelateGeotech).toHaveBeenCalledTimes(1))
    expect(deleteAutoCorrelations).not.toHaveBeenCalled()
    expect(subdivideAllBodies).not.toHaveBeenCalled()
    expect(acceptContactCorrelations).not.toHaveBeenCalled()
  })

  it('GC6 — no confirmation dialog stands between the press and the proposals', async () => {
    // "Subdivide all bodies" opens ReSubdivideConfirmDialog because a re-run destroys
    // manual work. This verb destroys nothing, so it must not inherit that friction.
    renderToolbar(makeCtx('geotechnical'))
    fireEvent.click(screen.getByTestId('geotech-auto-correlate'))
    await waitFor(() => expect(autoCorrelateGeotech).toHaveBeenCalled())
    expect(screen.queryByTestId('re-subdivide-confirm-dialog')).toBeNull()
  })

  it('GC7 — the toast reports banded restatements, new proposals, and what was left alone', async () => {
    // Owner refinement 2026-08-06: litho-backed restatements band silently;
    // only the machine's NEW packing claims arrive for review — the toast
    // must keep the three counts distinguishable.
    autoCorrelateGeotech.mockResolvedValueOnce({
      edges_proposed: 7,
      edges_accepted: 2,
      edges_skipped_existing: 4,
      sections_processed: 1,
      skipped_no_lcs: 0,
      skipped_empty_stack: 0,
    })
    const toast = vi.fn()
    renderToolbar(makeCtx('geotechnical', { toast }))
    fireEvent.click(screen.getByTestId('geotech-auto-correlate'))
    await waitFor(() => expect(toast).toHaveBeenCalled())
    const message = String(toast.mock.calls[0][1])
    expect(message).toContain('2 litho-backed')
    expect(message).toContain('7 new packing')
    expect(message).toContain('4 left untouched')
  })

  it('GC8 — proposals are announced as pending review, not as done work', async () => {
    autoCorrelateGeotech.mockResolvedValueOnce({
      edges_proposed: 3,
      edges_skipped_existing: 0,
      sections_processed: 1,
      skipped_no_lcs: 0,
      skipped_empty_stack: 0,
    })
    const toast = vi.fn()
    renderToolbar(makeCtx('geotechnical', { toast }))
    fireEvent.click(screen.getByTestId('geotech-auto-correlate'))
    await waitFor(() => expect(toast).toHaveBeenCalled())
    expect(String(toast.mock.calls[0][1])).toMatch(/accept|review|suggestion|propos/i)
  })
})

// ---------------------------------------------------------------------------
// GA — the geotech accept verb
// ---------------------------------------------------------------------------

describe('SectionsToolbar — geotech accept correlations', () => {
  it('GA1 — the accept verb is reachable on the geotech axis', () => {
    renderToolbar(makeCtx('geotechnical'))
    expect(screen.getByTestId('geotech-accept-correlations')).toBeTruthy()
  })

  it('GA2 — accepting promotes the GEOTECH model’s pending ties model-wide', async () => {
    // RE-PINNED 2026-08-05 (review MAJOR-2) — see GA3b for the reasoning.
    renderToolbar(makeCtx('geotechnical'))
    fireEvent.click(screen.getByTestId('geotech-accept-correlations'))
    await waitFor(() => expect(acceptContactCorrelations).toHaveBeenCalled())
    expect(acceptContactCorrelations).toHaveBeenCalledWith('proj-1', 'geotech-model-1', null)
  })

  it('GA3 — the accept verb is disabled until a geotech model exists', () => {
    renderToolbar(makeCtx('geotechnical', { geoModel: { activeGeotechModel: null } }))
    expect(screen.getByTestId('geotech-accept-correlations')).toBeDisabled()
  })

  it('GA3b — the accept verb works with no section open (model-wide)', () => {
    // RE-PINNED 2026-08-05 (review MAJOR-2). The earlier pin scoped accepting
    // to the open section — but step 4's gate and the pending chip count the
    // WHOLE model, so a section-scoped "Accept all" could never satisfy them:
    // on a multi-section model the gate stayed closed with no in-app escape.
    // The label says ALL and the owner's pipeline gates a model-wide divide on
    // it, so the verb is model-wide; the per-tie right-click accept remains
    // the section-local review path. (Trade-off flagged to the owner: bulk
    // accept approves ties on sections not currently on screen.)
    renderToolbar(makeCtx('geotechnical', { sections: { selectedSectionId: null } }))
    expect(screen.getByTestId('geotech-accept-correlations')).not.toBeDisabled()
  })

  it('GA3c — accepting reaches the whole model, matching the gate it must clear', async () => {
    renderToolbar(makeCtx('geotechnical'))
    fireEvent.click(screen.getByTestId('geotech-accept-correlations'))
    await waitFor(() => expect(acceptContactCorrelations).toHaveBeenCalled())
    // Model-wide on purpose — see GA3b. A section id here would re-open MAJOR-2.
    expect(acceptContactCorrelations.mock.calls[0][2]).toBeNull()
  })

  it('GA4 — the accept verb is absent on the litho axis (control)', () => {
    renderToolbar(makeCtx('lithostratigraphic'))
    expect(screen.queryByTestId('geotech-accept-correlations')).toBeNull()
    expect(screen.getByTestId('correlate-mode-caret')).toBeTruthy()
  })
})

// ---------------------------------------------------------------------------
// GP — the gesture the two verbs bracket stays where it was
// ---------------------------------------------------------------------------

describe('SectionsToolbar — Correlate packing keeps its own behaviour', () => {
  it('GP1 — the primary half still toggles packing-correlate mode', () => {
    const enterCorrelateMode = vi.fn()
    renderToolbar(makeCtx('geotechnical', { sections: { enterCorrelateMode } }))
    fireEvent.click(screen.getByTestId('geotech-correlate-packing'))
    expect(enterCorrelateMode).toHaveBeenCalled()
  })

  it('GP2 — the model-existence gate still applies to the gesture', () => {
    renderToolbar(
      makeCtx('geotechnical', {
        geoModel: { activeGeotechModel: null },
        sections: { correlateMode: false },
      }),
    )
    // Still not usable without a geotech model; the caret is the only live half.
    expect(screen.getByTestId('geotech-correlate-packing')).toBeTruthy()
  })

  it('GP4 — the destructive re-subdivide warning names the non-destructive alternative', () => {
    // ReSubdivideConfirmDialog existed because wiping the model was the ONLY way to
    // regenerate the automatic ties. It no longer is, and the moment the engineer
    // reads that warning is the moment he needs to know that.
    // Subdivide needs the litho model it reads bodies from; only then is its button
    // live and the re-run gated behind this dialog.
    renderToolbar(makeCtx('geotechnical', { geoModel: { activeLithoModel: makeLithoModel() } }))
    fireEvent.click(screen.getByTestId('geotech-subdivide-cpts'))
    const dialog = screen.getByTestId('re-subdivide-confirm-dialog')
    expect(dialog.textContent ?? '').toMatch(/auto-correlate/i)
  })

  it('GP3 — the geotech model fixture is the one the verbs address', () => {
    // Guards the assertions above against a fixture rename silently passing.
    expect(makeGeotechModel().id).toBe('geotech-model-1')
    expect(makeGeotechModel().kind).toBe('geotechnical')
  })
})
